import {readFileSync,writeFileSync} from 'node:fs';
import {discoverInventory,sourceHash} from '../scripts/quality-inventory';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
const group=JSON.parse(readFileSync('.git/b11-maintenance-group.json','utf8')) as string[];
const inputs=discoverInventory(process.cwd()).files.filter(f=>['src/presentation/cli/commands/backup.ts','src/presentation/cli/commands/migrate.ts','src/presentation/cli/db-startup.ts','scripts/eval-v5/evaluators.ts','src/infrastructure/database/connection.ts','src/infrastructure/database/owned-database.ts'].includes(f.path)||group.some(p=>p.endsWith('.ts')?p===f.path:f.path.startsWith(p+'/'))).map(f=>({path:f.path,sourceHash:f.sourceHash}));
const storage=createOwnedTestDirectory('memory-maintenance-compat-');
try{
 const command=[process.execPath,'test','--timeout','15000',...group];
 const result=Bun.spawnSync(command,{env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:60000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 writeFileSync('.git/b11-maintenance-compat.txt',output);
 for(const row of inputs)if(sourceHash(readFileSync(row.path,'utf8'))!==row.sourceHash)throw Error('Changed during execution '+row.path);
 writeFileSync('.git/b11-maintenance-compat.json',JSON.stringify({recordedAt:new Date().toISOString(),sourceInputs:inputs,command,exit:result.exitCode,output,source:readFileSync('.git/b11-maintenance-compat.ts','utf8')},null,2)+'\n');
 console.log(output.slice(-200));if(result.exitCode!==0)throw Error('Compatibility group failed');
}finally{storage.cleanup();}

